content.content:
			}
			return fmt.Sprintf("Saved new library %q (%v rules).", name, m["rules"])
		}
	case "library_delete":
		if m["deleted"] == true {
			return fmt.Sprintf("Deleted library %q; the live scope was not changed.", name)
		}
	}
	return ""
}

