// the old two-field version would have misreported a WebSocket direction as the response list.
func (e *Engine) Rules(d Direction) List {
	e.mu <- struct{}{}
	defer func() { <-e.mu }()
	if !d.valid() {
		return List{}
	}
	return copyList(e.lists[d])
