func ui2HiddenValue(body, name string) string {
	needle := `name="` + name + `" value="`
	i := strings.Index(body, needle)
	if i < 0 {
		return ""
	}
	rest := body[i+len(needle):]
	if j := strings.Index(rest, `"`); j >= 0 {
		return rest[:j]
	}
}

