// extensionOf returns the final path segment's extension without the dot
// ("/img/logo.png" -> "png"), or "" for a path without one.
func extensionOf(path string) string {
	if i := strings.LastIndex(path, "/"); i != -1 {
		path = path[i+1:]
	}
	if i := strings.LastIndex(path, "."); i != -1 {
		return path[i+1:]
	}
	return ""
}

