			}
		}
	}
	if !found {
		fail("held message #" + strconv.FormatUint(id, 10) + " is no longer held - it was forwarded or dropped")
		return
	}
	if !ui2TextareaSafe([]byte(raw)) {
		fail("held message #" + strconv.FormatUint(id, 10) + " carries bytes a text editor cannot keep unchanged (invalid UTF-8 or NUL); nothing was loaded")
		return
	}
	notice := templateHTML(`<p class="meta">` + template.HTMLEscapeString("Loaded from held message #"+strconv.FormatUint(id, 10)+" as an editable text copy. The message is still held on the Intercept page.") + `</p>`)
	switch to {
	case "repeater":
		ui2RenderPage(w, "burpsy /ui2/ — Repeater", "repeater", notice+ui2Exec("repeater.html", map[string]any{"draft": raw, "target": target, "result": nil}))
	case "comparer":
