	verb := "Dropped"
	if forward {
		verb = "Forwarded"
	}
	note := verb + " " + strconv.Itoa(len(ok)) + " checked message(s)"
	if len(ok) > 0 {
		note += " (" + strings.Join(ok, ", ") + ")"
	}
	if len(failed) > 0 {
		note += "; not resolved (no longer held or refused): " + strings.Join(failed, ", ")
	}
