		if h.ID == id && h.Host == host && h.Port == uint16(port) && h.TLS == (scheme == "https") {
			return "" // unchanged: send it where the client asked
		}
	}
	fwd["host"] = host
	fwd["port"] = port
	fwd["tls"] = scheme == "https"
	return ""
}

